package dev.eugheist.ttmodern;
/** Natural player ticks exercise the Baubles bridge, not a direct onWornTick call. */
final class CatAmuletWorldClientAudit {
 static boolean saved,checked;static net.minecraft.world.item.ItemStack old;static net.minecraft.world.entity.monster.Creeper near,above;static int entityId;
 static void restore(net.minecraft.client.Minecraft mc){if(!saved)return;var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());dev.eugheist.tc4modern.BaublesInventory.of(p).setItem(0,old);if(near!=null)near.discard();if(above!=null)above.discard();saved=false;}
 static void tick(net.minecraft.client.Minecraft mc,int t){
  if(t==1240)mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());var baubles=dev.eugheist.tc4modern.BaublesInventory.of(p);old=baubles.getItem(0).copy();saved=true;near=net.minecraft.world.entity.EntityType.CREEPER.create(p.level());above=net.minecraft.world.entity.EntityType.CREEPER.create(p.level());near.setPos(p.getX()+2,p.getY(),p.getZ());above.setPos(p.getX()+2,p.getY()+8,p.getZ());for(var mob:java.util.List.of(near,above)){mob.setNoAi(true);mob.setNoGravity(true);mob.setTarget(p);p.serverLevel().addFreshEntity(mob);}entityId=near.getId();baubles.setItem(0,new net.minecraft.world.item.ItemStack(CatAmulet.ITEM.get()));}).join();
  if(t==1255){EnchanterClientAudit.check(mc.level.getEntity(entityId)!=null,"cat amulet native creeper spawn packet");mc.getSingleplayerServer().submit(()->{var p=mc.getSingleplayerServer().getPlayerList().getPlayer(mc.player.getUUID());var goals=((dev.eugheist.ttmodern.mixin.CatMobAccessor)near).ttinkerer$targets().getAvailableGoals();EnchanterClientAudit.check(goals.stream().anyMatch(g->g.getGoal() instanceof CatAmulet.TargetGoal target&&target.ttinkerer$targetType()==net.minecraft.world.entity.boss.enderdragon.EndCrystal.class)&&near.getTarget()==null,"natural worn Baubles ticks mutate creeper goal and clear target");EnchanterClientAudit.check(((dev.eugheist.ttmodern.mixin.CatMobAccessor)above).ttinkerer$targets().getAvailableGoals().stream().anyMatch(g->g.getGoal() instanceof CatAmulet.TargetGoal target&&target.ttinkerer$targetType()==net.minecraft.world.entity.player.Player.class),"original four-block vertical range excludes high mob");dev.eugheist.tc4modern.BaublesInventory.of(p).setItem(0,net.minecraft.world.item.ItemStack.EMPTY);}).join();}
  if(t==1270)mc.getSingleplayerServer().submit(()->{try{EnchanterClientAudit.check(((dev.eugheist.ttmodern.mixin.CatMobAccessor)near).ttinkerer$targets().getAvailableGoals().stream().anyMatch(g->g.getGoal() instanceof CatAmulet.TargetGoal target&&target.ttinkerer$targetType()==net.minecraft.world.entity.boss.enderdragon.EndCrystal.class),"original goal mutation remains after amulet removal");checked=true;System.out.println("TT CAT AMULET WORLD CLIENT AUDIT: ALL PASS (natural Baubles worn ticks,creeper spawn packet,target cleared,vertical bound,persistent mutation after removal,restored fixture)");}finally{restore(mc);}}).join();
 }
}
